-- v31: passkeys (WebAuthn)
CREATE TABLE IF NOT EXISTS user_passkeys(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, cred_id VARCHAR(400) NOT NULL, pubkey TEXT NOT NULL, sign_count BIGINT NOT NULL DEFAULT 0, name VARCHAR(80) NOT NULL DEFAULT 'Passkey', created DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, last_used DATETIME NULL, UNIQUE KEY(cred_id), INDEX(user_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
